class WordPieceTokenizer:
    def __init__(self, vocab: list[str]):
        self.vocab = set(vocab)

    def tokenize(self, text: str) -> list[str]:
        tokens = ["[CLS]"]
        for word in text.lower().split():
            start = 0
            while start < len(word):
                end = len(word)
                match = None
                while end > start:
                    piece = word[start:end]
                    if start > 0:
                        piece = "##" + piece
                    if piece in self.vocab:
                        match = piece
                        break
                    end -= 1
                if match is None:
                    tokens.append("[UNK]")
                    start += 1
                else:
                    tokens.append(match)
                    start = end
        tokens.append("[SEP]")
        return tokens


vocab = ["transfer", "learn", "##ing", "is", "un", "##stop",
